//字模高度：19
//内部字体
//未用排序和顺序查表
const lv_font_t yahei_regular_10 = {
    .dsc = &font_dsc,
    .get_glyph_bitmap = __user_font_get_bitmap,
    .get_glyph_dsc = __user_font_get_glyph_dsc,
    .line_height = 19,
    .base_line = 0,
};

